key.query:
query GetProductBySlug($slug: ID!) {
  product(id: $slug, idType: SLUG) {
    id
    databaseId
    name
    slug
    description
    shortDescription
    image {
      sourceUrl
      mediaDetails {
        sizes {
          sourceUrl
          name
          __typename
        }
        __typename
      }
      __typename
    }
    galleryImages {
      nodes {
        sourceUrl
        mediaDetails {
          sizes {
            sourceUrl
            name
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    productCategories {
      nodes {
        name
        slug
        parent {
          node {
            name
            slug
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    ... on SimpleProduct {
      price
      regularPrice
      onSale
      stockStatus
      __typename
    }
    ... on VariableProduct {
      price
      regularPrice
      onSale
      attributes {
        nodes {
          name
          options
          __typename
        }
        __typename
      }
      variations {
        nodes {
          name
          price
          stockStatus
          attributes {
            nodes {
              name
              value
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
